package com.api.group.domain

enum class Pricing {
    Free,
    Advanced,
    Premiun,
}

package com.api.group.domain

enum class Permission {
    Viewer,
    Editor,
    Admin,
}

package com.api.group.persistence

import com.api.group.domain.Permission
import com.api.group.domain.Pricing
import org.jetbrains.exposed.v1.jdbc.insert
import org.jetbrains.exposed.v1.jdbc.selectAll
import org.springframework.boot.ApplicationArguments
import org.springframework.boot.ApplicationRunner
import org.springframework.context.annotation.Profile
import org.springframework.core.annotation.Order
import org.springframework.stereotype.Component
import org.springframework.transaction.annotation.Transactional

@Component
@Profile("sample-data")
@Order(1)
class SampleDataInitializer : ApplicationRunner {

    @Transactional
    override fun run(args: ApplicationArguments) {
        if (Groups.selectAll().count() != 0L) return

        val groups = Pricing.entries.associateWith { pricing ->
            Groups.insert {
                it[name] = "${pricing.name} 샘플 그룹"
                it[Groups.pricing] = pricing
            }[Groups.id]
        }
        // The member sample dataset assigns IDs 1..4 in a fresh in-memory DB.
        listOf(
            Triple(Pricing.Free, 1L, Permission.Admin),
            Triple(Pricing.Free, 2L, Permission.Editor),
            Triple(Pricing.Advanced, 3L, Permission.Viewer),
            Triple(Pricing.Premiun, 4L, Permission.Admin),
        ).forEach { (pricing, memberId, permission) ->
            GroupMembers.insert {
                it[groupId] = groups.getValue(pricing)
                it[GroupMembers.memberId] = memberId
                it[GroupMembers.permission] = permission
            }
        }
    }
}

