package com.api.group.persistence

import com.api.group.api.dto.GroupMembershipResponse
import org.jetbrains.exposed.v1.core.inList
import org.jetbrains.exposed.v1.jdbc.select
import org.springframework.stereotype.Repository
import org.springframework.transaction.annotation.Transactional

@Repository
class GroupMembershipRepository {

    @Transactional(readOnly = true)
    fun findByMemberIds(memberIds: List<String>): List<GroupMembershipResponse> =
        (GroupMembers innerJoin Groups)
            .select(GroupMembers.memberId, Groups.name, GroupMembers.permission)
            .where { GroupMembers.memberId inList memberIds }
            .map { GroupMembershipResponse(it[GroupMembers.memberId], it[Groups.name], it[GroupMembers.permission]) }
}

