package com.api.member.service

import com.api.member.api.dto.MemberListResponse
import com.api.member.api.dto.MemberResponse
import com.api.member.client.GroupMembershipClient
import com.api.member.persistence.MemberNameOrder
import com.api.member.persistence.MemberRepository
import org.springframework.stereotype.Service

@Service
class MemberQueryService(
    private val members: MemberRepository,
    private val groups: GroupMembershipClient,
) {
    fun findMembers(page: Int, size: Int, order: MemberNameOrder?): MemberListResponse {
        // The local read transaction is complete before calling the group service.
        val pageMembers = members.findPage(page, size, order)
        val memberships = groups.findByMemberIds(pageMembers.map { it.id })
        return MemberListResponse(pageMembers.map { member ->
            val membership = memberships[member.id]
            MemberResponse(member.id, member.name, membership?.group, membership?.permission)
        })
    }
}

package com.api.member.config

import org.slf4j.MDC
import org.springframework.boot.context.properties.ConfigurationProperties
import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.http.client.JdkClientHttpRequestFactory
import org.springframework.web.client.RestClient
import java.net.URI
import java.net.http.HttpClient
import java.time.Duration

@ConfigurationProperties("clients.group-service")
data class GroupServiceProperties(
    val baseUrl: URI,
    val connectTimeout: Duration = Duration.ofSeconds(2),
    val readTimeout: Duration = Duration.ofSeconds(3),
)

@Configuration(proxyBeanMethods = false)
@EnableConfigurationProperties(GroupServiceProperties::class)
class GroupServiceClientConfiguration {

    @Bean
    fun groupServiceRestClient(builder: RestClient.Builder, properties: GroupServiceProperties): RestClient {
        val httpClient = HttpClient.newBuilder().connectTimeout(properties.connectTimeout).build()
        val requestFactory = JdkClientHttpRequestFactory(httpClient)
        requestFactory.setReadTimeout(properties.readTimeout)
        return builder.baseUrl(properties.baseUrl.toString())
            .requestFactory(requestFactory)
            .requestInterceptor { request, body, execution ->
                MDC.get("requestId")?.let { request.headers.set("X-Request-Id", it) }
                execution.execute(request, body)
            }
            .build()
    }
}

package com.api.member.persistence

import org.jetbrains.exposed.v1.core.SortOrder
import org.jetbrains.exposed.v1.jdbc.select
import org.springframework.stereotype.Repository
import org.springframework.transaction.annotation.Transactional

enum class MemberNameOrder { ASC, DESC }

data class MemberRecord(val id: String, val name: String)

@Repository
class MemberRepository {

    @Transactional(readOnly = true)
    fun findPage(page: Int, size: Int, order: MemberNameOrder?): List<MemberRecord> {
        val query = Members.select(Members.id, Members.name)
        if (order != null) {
            val direction = if (order == MemberNameOrder.ASC) SortOrder.ASC else SortOrder.DESC
            query.orderBy(Members.name to direction, Members.id to SortOrder.ASC)
        }
        return query.limit(size).offset(page.toLong() * size).map {
            MemberRecord(it[Members.id], it[Members.name])
        }
    }
}

