package com.api.member.application.query

import com.api.member.domain.MembershipPermission
import com.api.member.logging.LogCapture
import com.api.member.logging.fields
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test
import org.slf4j.MDC

class GetMembersQueryHandlerTests {
    @Test
    fun `read models preserve ordering and query logs expose counts without member data`() {
        val query = GetMembersQuery(1, 2, MemberNameOrder.DESC)
        val handler = GetMembersQueryHandler(
            MemberReadPort {
                assertEquals(query, it)
                listOf(MemberSummary("second", "private-name"), MemberSummary("first", "another-name"))
            },
            GroupMembershipReadPort { ids ->
                assertEquals(listOf("second", "first"), ids)
                mapOf("first" to GroupMembershipReadModel("first", "private-group", MembershipPermission.Editor))
            },
        )
        MDC.put("requestId", "cqrs-unit-query")
        try {
            LogCapture(GetMembersQueryHandler::class.java).use { capture ->
                val result = handler.handle(query)
                assertEquals(listOf("second", "first"), result.members.map { it.id })
                assertNull(result.members[0].group)
                assertNull(result.members[0].permission)
                assertEquals("private-group", result.members[1].group)
                val event = capture.events.single()
                val fields = event.fields()
                assertEquals("member.query.completed", fields["eventType"])
                assertEquals(2, fields["returnedCount"])
                assertEquals(1, fields["groupedCount"])
                assertEquals("DESC", fields["sort"])
                assertTrue((fields["durationMs"] as Long) >= 0)
                assertEquals("cqrs-unit-query", event.mdcPropertyMap["requestId"])
                assertFalse((fields.toString() + event.formattedMessage).contains("private-"))
            }
        } finally { MDC.clear() }
    }

    @Test
    fun `empty pages do not invoke the external read port`() {
        val handler = GetMembersQueryHandler(MemberReadPort { emptyList() }, GroupMembershipReadPort { error("must not call") })
        assertTrue(handler.handle(GetMembersQuery(0)).members.isEmpty())
    }

    @Test
    fun `upstream failure remains a failure and logs a sanitized reason`() {
        val failure = GroupMembershipLookupException(GroupLookupFailureReason.HTTP_ERROR, 503, RuntimeException("secret-upstream-body"))
        val handler = GetMembersQueryHandler(MemberReadPort { listOf(MemberSummary("member1", "private-name")) },
            GroupMembershipReadPort { throw failure })
        LogCapture(GetMembersQueryHandler::class.java).use { capture ->
            assertSame(failure, assertThrows(GroupMembershipLookupException::class.java) { handler.handle(GetMembersQuery(0)) })
            val event = capture.events.single()
            assertEquals("member.query.failed", event.fields()["eventType"])
            assertEquals("group-service", event.fields()["stage"])
            assertEquals("HTTP_ERROR", event.fields()["failureReason"])
            assertEquals(503, event.fields()["upstreamStatus"])
            assertFalse((event.fields().toString() + event.formattedMessage).contains("secret-upstream-body"))
            assertNull(event.throwableProxy)
        }
    }

    @Test
    fun `local read failures identify the store stage`() {
        val handler = GetMembersQueryHandler(MemberReadPort { error("private-database-error") },
            GroupMembershipReadPort { error("must not call") })
        LogCapture(GetMembersQueryHandler::class.java).use { capture ->
            assertThrows(IllegalStateException::class.java) { handler.handle(GetMembersQuery(0)) }
            assertEquals("member-store", capture.events.single().fields()["stage"])
            assertEquals("READ_FAILURE", capture.events.single().fields()["failureReason"])
            assertFalse(capture.events.single().formattedMessage.contains("private-database-error"))
        }
    }
}

package com.api.group.application.command

import com.api.group.application.query.GroupMembershipReadPort
import com.api.group.domain.Permission
import com.api.group.domain.Pricing
import com.api.group.logging.LogCapture
import com.api.group.logging.fields
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.jdbc.core.JdbcTemplate
import javax.sql.DataSource

@SpringBootTest(properties = [
    "spring.datasource.url=jdbc:h2:mem:group-command-tests;DB_CLOSE_DELAY=-1;DB_CLOSE_ON_EXIT=FALSE",
    "logging.file.name=build/test-logs/group-command.jsonl",
])
class InitializeGroupsCommandTests @Autowired constructor(
    private val handler: InitializeGroupsCommandHandler,
    private val reads: GroupMembershipReadPort,
    dataSource: DataSource,
) {
    private val jdbc = JdbcTemplate(dataSource)
    private fun group(name: String, memberId: String) = InitialGroup(name, Pricing.Free, listOf(InitialMembership(memberId, Permission.Admin)))
    @BeforeEach fun clear() {
        jdbc.update("DELETE FROM \"group_member\"")
        jdbc.update("DELETE FROM \"group\"")
    }

    @Test
    fun `groups and memberships commit together and are queryable`() {
        val result = handler.handle(InitializeGroupsCommand(listOf(group("team1", "one"), group("team2", "two"))))
        assertEquals(InitializeGroupsResult(2, 2, false), result)
        val memberships = reads.findByMemberIds(listOf("one", "two")).associateBy { it.memberId }
        assertEquals("team1", memberships.getValue("one").group)
        assertEquals("team2", memberships.getValue("two").group)
    }

    @Test
    fun `existing groups are not overwritten`() {
        handler.handle(InitializeGroupsCommand(listOf(group("existing", "one"))))
        assertEquals(InitializeGroupsResult(0, 0, true), handler.handle(InitializeGroupsCommand(listOf(group("new", "two")))))
        assertEquals(listOf("one"), reads.findByMemberIds(listOf("one", "two")).map { it.memberId })
    }

    @Test
    fun `membership conflicts roll back all groups and memberships in the command`() {
        LogCapture(InitializeGroupsCommandHandler::class.java).use { capture ->
            assertThrows(RuntimeException::class.java) {
                handler.handle(InitializeGroupsCommand(listOf(group("team1", "duplicate"), group("team2", "duplicate"))))
            }
            assertEquals(0L, jdbc.queryForObject("SELECT COUNT(*) FROM \"group\"", Long::class.java))
            assertEquals(0L, jdbc.queryForObject("SELECT COUNT(*) FROM \"group_member\"", Long::class.java))
            assertEquals(listOf("group.command.failed"), capture.events.map { it.fields()["eventType"] })
        }
    }
}

package com.api.member.application.command

import com.api.member.application.query.GetMembersQuery
import com.api.member.application.query.MemberReadPort
import com.api.member.logging.LogCapture
import com.api.member.logging.fields
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.jdbc.core.JdbcTemplate
import javax.sql.DataSource

@SpringBootTest(properties = [
    "spring.datasource.url=jdbc:h2:mem:member-command-tests;DB_CLOSE_DELAY=-1;DB_CLOSE_ON_EXIT=FALSE",
    "logging.file.name=build/test-logs/member-command.jsonl",
])
class InitializeMembersCommandTests @Autowired constructor(
    private val handler: InitializeMembersCommandHandler,
    private val reads: MemberReadPort,
    dataSource: DataSource,
) {
    private val jdbc = JdbcTemplate(dataSource)
    private fun member(id: String) = InitialMember(id, "private-name", "$***", "private-address")
    @BeforeEach fun clear() { jdbc.update("DELETE FROM \"member\"") }

    @Test
    fun `a committed command is visible through the independent read port`() {
        LogCapture(InitializeMembersCommandHandler::class.java).use { capture ->
            val result = handler.handle(InitializeMembersCommand(listOf(member("one"), member("two"))))
            assertEquals(InitializeMembersResult(2, false), result)
            assertEquals(setOf("one", "two"), reads.findPage(GetMembersQuery(0)).map { it.id }.toSet())
            assertEquals("member.command.completed", capture.events.single().fields()["eventType"])
            assertFalse((capture.events.single().fields().toString() + capture.events.single().formattedMessage).contains("private-"))
        }
    }

    @Test
    fun `initialization preserves existing members`() {
        handler.handle(InitializeMembersCommand(listOf(member("existing"))))
        val result = handler.handle(InitializeMembersCommand(listOf(member("new"))))
        assertEquals(InitializeMembersResult(0, true), result)
        assertEquals(listOf("existing"), reads.findPage(GetMembersQuery(0)).map { it.id })
    }

    @Test
    fun `a partially failing write rolls back the entire command without success logging`() {
        LogCapture(InitializeMembersCommandHandler::class.java).use { capture ->
            assertThrows(RuntimeException::class.java) {
                handler.handle(InitializeMembersCommand(listOf(member("duplicate"), member("duplicate"))))
            }
            assertTrue(reads.findPage(GetMembersQuery(0)).isEmpty())
            assertEquals(listOf("member.command.failed"), capture.events.map { it.fields()["eventType"] })
        }
    }
}

package com.api.group.application.query

import com.api.group.domain.Permission
import com.api.group.logging.LogCapture
import com.api.group.logging.fields
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test

class GetGroupMembershipsQueryHandlerTests {
    @Test
    fun `duplicates are removed before the read port and only counts are logged`() {
        val handler = GetGroupMembershipsQueryHandler(GroupMembershipReadPort { ids ->
            assertEquals(listOf("member1", "member2"), ids)
            listOf(GroupMembershipReadModel("member1", "private-group", Permission.Viewer))
        })
        LogCapture(GetGroupMembershipsQueryHandler::class.java).use { capture ->
            val result = handler.handle(GetGroupMembershipsQuery(listOf("member1", "member2", "member1")))
            assertEquals(1, result.memberships.size)
            val event = capture.events.single()
            assertEquals("group.query.completed", event.fields()["eventType"])
            assertEquals(2, event.fields()["requestedCount"])
            assertEquals(1, event.fields()["returnedCount"])
            assertFalse((event.formattedMessage + event.fields()).contains("private-group"))
        }
    }

    @Test
    fun `read failures are rethrown and recorded`() {
        val handler = GetGroupMembershipsQueryHandler(GroupMembershipReadPort { error("private-database-error") })
        LogCapture(GetGroupMembershipsQueryHandler::class.java).use { capture ->
            assertThrows(IllegalStateException::class.java) { handler.handle(GetGroupMembershipsQuery(listOf("member1"))) }
            assertEquals("group.query.failed", capture.events.single().fields()["eventType"])
            assertNull(capture.events.single().throwableProxy)
        }
    }
