package com.api.group.infrastructure.persistence

import com.api.group.application.query.*
import com.api.group.infrastructure.persistence.table.GroupMembers
import com.api.group.infrastructure.persistence.table.Groups
import org.jetbrains.exposed.v1.core.count
import org.jetbrains.exposed.v1.core.eq
import org.jetbrains.exposed.v1.core.inList
import org.jetbrains.exposed.v1.jdbc.select
import org.springframework.stereotype.Repository
import org.springframework.transaction.annotation.Transactional

@Repository
class ExposedGroupInfoReadAdapter : GroupInfoReadPort {
    @Transactional(readOnly = true)
    override fun findByMemberId(memberId: String): GroupDetailReadModel? =
        (GroupMembers innerJoin Groups)
            .select(GroupMembers.memberId, Groups.id, Groups.name, GroupMembers.registeredDate, Groups.pricing, GroupMembers.permission)
            .where { GroupMembers.memberId eq memberId }.singleOrNull()?.let {
                GroupDetailReadModel(it[GroupMembers.memberId], it[Groups.id], it[Groups.name],
                    it[GroupMembers.registeredDate], it[Groups.pricing], it[GroupMembers.permission])
            }

    @Transactional(readOnly = true)
    override fun summarizeByMemberIds(memberIds: List<String>): List<GroupSummaryReadModel> {
        if (memberIds.isEmpty()) return emptyList()
        val rows = (GroupMembers innerJoin Groups)
            .select(Groups.id, Groups.name, GroupMembers.memberId, GroupMembers.permission)
            .where { GroupMembers.memberId inList memberIds }.toList()
        if (rows.isEmpty()) return emptyList()
        val groupIds = rows.map { it[Groups.id] }.distinct()
        val memberCount = GroupMembers.memberId.count()
        val totals = GroupMembers.select(GroupMembers.groupId, memberCount)
            .where { GroupMembers.groupId inList groupIds }.groupBy(GroupMembers.groupId)
            .associate { it[GroupMembers.groupId] to it[memberCount] }
        return rows.groupBy { it[Groups.id] }.map { (id, members) ->
            GroupSummaryReadModel(id, members.first()[Groups.name], totals.getValue(id),
                members.map { GroupSummaryMember(it[GroupMembers.memberId], it[GroupMembers.permission]) }.sortedBy { it.memberId })
        }.sortedBy { it.groupId }
    }
}

package com.api.group.application.query

import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.util.concurrent.TimeUnit

data class GetGroupByMemberQuery(val memberId: String)
data class GetGroupsSummaryQuery(val memberIds: List<String>)

@Service
class GetGroupInfoQueryHandler(private val groups: GroupInfoReadPort) {
    private val log = LoggerFactory.getLogger(javaClass)

    fun handle(query: GetGroupByMemberQuery): GroupDetailReadModel? = logged("GetGroupByMember", 1) {
        groups.findByMemberId(query.memberId)
    }

    fun handle(query: GetGroupsSummaryQuery): GroupsSummaryReadModel = logged("GetGroupsSummary", query.memberIds.distinct().size) {
        GroupsSummaryReadModel(groups.summarizeByMemberIds(query.memberIds.distinct()))
    }

    private fun <T> logged(operation: String, requestedCount: Int, block: () -> T): T {
        val started = System.nanoTime()
        try {
            val result = block()
            log.atInfo().addKeyValue("eventType", "group.info.query.completed")
                .addKeyValue("cqrs", "query").addKeyValue("operation", operation)
                .addKeyValue("requestedCount", requestedCount)
                .addKeyValue("durationMs", TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started))
                .log("{} completed (requested={})", operation, requestedCount)
            return result
        } catch (exception: Exception) {
            log.atError().addKeyValue("eventType", "group.info.query.failed")
                .addKeyValue("cqrs", "query").addKeyValue("operation", operation)
                .addKeyValue("failureReason", "READ_FAILURE").addKeyValue("errorType", exception.javaClass.simpleName)
                .addKeyValue("durationMs", TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started))
                .log("{} failed (reason=READ_FAILURE)", operation)
            throw exception
        }
    }
}

